// Some portions generated by Claude
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// What the Graph page draws with Values on: label values that repeat a card's title are not drawn again, and the type
// links of a class with many instances stay collapsed until one of its cards is pointed at.
const REPOSITORY_ID = uniqueRepositoryId('graph-layout');
const PEOPLE = Array.from({ length: 7 }, (_, i) => `Person ${i + 1}`);
const DATA = `
@prefix ex: <http://example.org/layout/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:Person rdfs:label "Human" .
${PEOPLE.map((name, i) => `ex:p${i} a ex:Person ; rdfs:label "${name}" ; ex:age ${20 + i}${i ? ` ; ex:knows ex:p${i - 1}` : ''} .`).join('\n')}
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph layout')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, { headers: { 'Content-Type': 'text/turtle' }, data: DATA });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

function node(explorer, label) {
    return explorer.locator('.graph-node').filter({ has: explorer.page().locator('text', { hasText: label }) }).first();
}

async function openWithValues(page) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(node(explorer, 'Person 7')).toBeAttached({ timeout: 30000 });
    const values = explorer.getByRole('button', { name: 'Show values and types as nodes' });
    if ((await values.getAttribute('aria-pressed')) !== 'true') await values.click();
    await expect(node(explorer, 'Human')).toBeAttached();
    await page.waitForTimeout(1200);
    return explorer;
}

test('with Values on, a label value is not drawn again next to the card it titles', async ({ page }) => {
    const explorer = await openWithValues(page);
    await expect(explorer.locator('.graph-node.literal', { hasText: '26' })).toBeAttached();
    await expect(explorer.locator('.graph-node.literal', { hasText: 'Person 3' })).toHaveCount(0);
    await expect(explorer.locator('.graph-node.literal')).toHaveCount(7);
});

test('the type links of a class with many instances appear only for the card pointed at', async ({ page }) => {
    const explorer = await openWithValues(page);
    await expect(explorer.locator('g.edge title', { hasText: '→ Human' })).toHaveCount(0);
    await expect(explorer.locator('.class-link')).toHaveCount(0);
    await node(explorer, 'Person 3').hover();
    await expect(explorer.locator('.class-link')).toHaveCount(1);
    await node(explorer, 'Human').hover();
    await expect(explorer.locator('.class-link')).toHaveCount(7);
});
